"use client";

import {
  addDays,
  differenceInCalendarDays,
  eachDayOfInterval,
  format,
  isSameDay,
} from "date-fns";
import type { Locale } from "date-fns";
import * as React from "react";

import { cn } from "@/lib/utils";
import {
  formatHourLabel,
  getPeriodStart,
  getVisibleDayCount,
  getWeekViewStepDays,
  isMultiDayEvent,
} from "@/lib/event-utils";
import { useHorizontalScroll } from "@/hooks/use-horizontal-scroll";
import { useEventKeyboard } from "@/hooks/use-event-keyboard";
import { useEventDrag } from "@/hooks/use-event-drag";
import { useEventResize } from "@/hooks/use-event-resize";
import { useAllDayResize } from "@/hooks/use-all-day-resize";
import { useToday } from "@/hooks/use-now";
import { useTimeZoneLabel } from "@/hooks/use-timezone-label";
import type {
  CalendarEvent,
  HourCycle,
  HourSlot,
  TimeGridProps,
  TimeGridView,
  WeekDay,
} from "./week-view-types";
import {
  useCalendar,
  useCalendarConfig,
  useCalendarViewSync,
} from "./calendar-provider";
import { WeekViewAllDayRow } from "./week-view-all-day-row";
import { CalendarDayHeaders } from "./calendar-day-headers";
import { WeekViewGrid } from "./week-view-grid";
import { WeekViewTimeAxis } from "./week-view-time-axis";
import { WeekViewTimeIndicator } from "./week-view-time-indicator";
import {
  CalendarPopoverBoundaryProvider,
  isEventInsideCalendarPopover,
} from "./calendar-popover-context";
import { CalendarLoadingBar } from "./calendar-loading-bar";

/** Minimum height of each hour row in pixels */
const MIN_HOUR_HEIGHT = 48;

/** Width of the time axis column in pixels (4rem = 64px) */
export const TIME_AXIS_WIDTH = 64;

/** Buffer days per view mode (each side, for horizontal scroll) */
const BUFFER_DAYS_BY_VIEW: Record<TimeGridView, number> = {
  day: 1,
  week: 7,
};

/** Buffer extension step size per view mode */
const BUFFER_STEP_BY_VIEW: Record<TimeGridView, number> = {
  day: 1,
  week: 7,
};

/** Days the day view moves when a drag or resize is held at its side edge */
const DAY_VIEW_EDGE_NAV_DAYS = 7;

/**
 * Generates an array of WeekDay objects starting from the given date.
 * Note: isToday is added separately from the shared `useToday` clock, so it
 * stays correct across midnight and is never computed on the server
 */
function generateWeekDays(
  startDate: Date,
  count: number,
  locale: Locale,
): Omit<WeekDay, "isToday">[] {
  const end = addDays(startDate, count - 1);

  return eachDayOfInterval({ start: startDate, end }).map((date) => ({
    date,
    dayName: format(date, "EEE", { locale }),
    dayNumber: date.getDate(),
  }));
}

/**
 * Generates an extended array of days including buffer days on both sides
 * for smooth horizontal scroll transitions
 */
function generateBufferedDays(
  startDate: Date,
  bufferDays: number,
  visibleDays: number,
  locale: Locale,
): Omit<WeekDay, "isToday">[] {
  const bufferStart = addDays(startDate, -bufferDays);
  const bufferEnd = addDays(startDate, visibleDays + bufferDays - 1);

  return eachDayOfInterval({ start: bufferStart, end: bufferEnd }).map(
    (date) => ({
      date,
      dayName: format(date, "EEE", { locale }),
      dayNumber: date.getDate(),
    }),
  );
}

/**
 * Generates an HourSlot for each visible hour, from `dayStartHour` up to
 * (not including) `dayEndHour`
 */
function generateHours(
  dayStartHour: number,
  dayEndHour: number,
  hourCycle: HourCycle,
  locale: Locale,
): HourSlot[] {
  return Array.from({ length: dayEndHour - dayStartHour }, (_, i) => {
    const hour = dayStartHour + i;
    return { hour, label: formatHourLabel(hour, hourCycle, locale) };
  });
}

/** Marks the day matching `today` (none while `today` is unknown). */
function withIsToday(
  days: Omit<WeekDay, "isToday">[],
  today: Date | null,
): WeekDay[] {
  return days.map((day) => ({
    ...day,
    isToday: today !== null && isSameDay(day.date, today),
  }));
}

/**
 * Hourly time grid behind DayView and WeekView: day headers, the all-day
 * row, the time axis and the timed-event columns, with horizontal scroll
 * navigation. `view` sets the column count (one day, or `numberOfDays`);
 * date, events and selection come from the surrounding CalendarProvider,
 * which adopts `view` and `numberOfDays` while it doesn't control them.
 *
 * Changing `view` re-lays out the same grid instead of remounting it, so
 * driving it from the provider (`<TimeGrid view={view} />`) keeps the
 * vertical scroll position across day/week switches.
 *
 * Renders the same markup on the server and during hydration: everything that
 * depends on the viewer's clock (today, the current-time line, past events)
 * reads the shared `useNow` clock, which is unknown until hydration finishes.
 */
export function TimeGrid({
  view,
  numberOfDays: numberOfDaysProp,
  showEventPopover = true,
  onEventPopoverExpand,
  scrollToHour,
  className,
}: TimeGridProps) {
  const {
    view: providerView,
    currentDate,
    events,
    selectedEvent,
    highlightedDate,
    selectEvent,
    clearSelection,
    addEventFromRange,
    updateEvent,
    goToDate,
    goToPrev,
    goToNext,
    numberOfDays: providerNumberOfDays,
    weekStartsOn,
    loading,
  } = useCalendar();
  const { snapMinutes, dayStartHour, dayEndHour, hourCycle, locale } =
    useCalendarConfig();
  const { reportView, reportVisibleDays, closeEventPopover } =
    useCalendarViewSync();
  const numberOfDays = numberOfDaysProp ?? providerNumberOfDays;
  /** Day columns this grid pins the provider to (none in day view) */
  const fixedNumberOfDays = view === "week" ? numberOfDaysProp : undefined;
  /**
   * Whether the provider navigates by this grid's type and day count. False
   * for the commit before it adopts them (on mount, or right after a switch
   * this grid doesn't follow).
   */
  const isProviderInSync =
    providerView === view &&
    (fixedNumberOfDays === undefined ||
      providerNumberOfDays === fixedNumberOfDays);
  // `null` on the server and during hydration
  const today = useToday();
  const selectedEventId = selectedEvent?.id;
  const VISIBLE_DAYS = getVisibleDayCount(view, numberOfDays);
  const visibleHourCount = dayEndHour - dayStartHour;
  // A drag held at the grid's side edge moves by one prev/next step
  const edgeNavigationDays =
    view === "day" ? DAY_VIEW_EDGE_NAV_DAYS : getWeekViewStepDays(numberOfDays);
  const BUFFER_DAYS = BUFFER_DAYS_BY_VIEW[view];
  const BUFFER_STEP = BUFFER_STEP_BY_VIEW[view];
  const scrollContainerRef = React.useRef<HTMLDivElement>(null);
  const dayColumnsScrollRef = React.useRef<HTMLDivElement>(null);
  const allDayScrollRef = React.useRef<HTMLDivElement>(null);
  const allDayScrollContentRef = React.useRef<HTMLDivElement>(null);

  // Visible days starting from currentDate
  const baseDays = React.useMemo(
    () => generateWeekDays(currentDate, VISIBLE_DAYS, locale),
    [currentDate, VISIBLE_DAYS, locale],
  );

  const days = withIsToday(baseDays, today);

  const hours = React.useMemo(
    () => generateHours(dayStartHour, dayEndHour, hourCycle, locale),
    [dayStartHour, dayEndHour, hourCycle, locale],
  );

  const allDayEvents = React.useMemo(
    () => events.filter((e) => e.isAllDay || isMultiDayEvent(e)),
    [events],
  );

  const timedEvents = React.useMemo(
    () => events.filter((e) => !e.isAllDay && !isMultiDayEvent(e)),
    [events],
  );

  // Compute day column width and dynamic hour height from container
  const [dayColumnWidth, setDayColumnWidth] = React.useState(0);
  const [hourHeight, setHourHeight] = React.useState(MIN_HOUR_HEIGHT);
  const [contextMenuOpen, setContextMenuOpen] = React.useState(false);
  const [isAllDayResizing, setIsAllDayResizing] = React.useState(false);
  // Empty on the server and during hydration, the viewer's zone afterwards
  const timeZoneLabel = useTimeZoneLabel();

  React.useEffect(() => {
    const updateDimensions = () => {
      const container = scrollContainerRef.current;
      if (!container) return;
      const availableWidth = container.clientWidth - TIME_AXIS_WIDTH;
      setDayColumnWidth(availableWidth / VISIBLE_DAYS);
      setHourHeight(
        Math.max(MIN_HOUR_HEIGHT, container.clientHeight / visibleHourCount),
      );
    };

    updateDimensions();

    const observer = new ResizeObserver(updateDimensions);
    if (scrollContainerRef.current) {
      observer.observe(scrollContainerRef.current);
    }
    return () => observer.disconnect();
  }, [VISIBLE_DAYS, visibleHourCount]);

  /** Whether `scrollToHour` has been applied; it only applies once */
  const hasScrolledToHourRef = React.useRef(false);

  // Scroll to `scrollToHour` before the first paint. A grid mounted hidden
  // (e.g. in an inactive tab) has no height yet, so wait until it has one.
  React.useLayoutEffect(() => {
    if (scrollToHour === undefined || hasScrolledToHourRef.current) return;
    const container = scrollContainerRef.current;
    if (!container) return;

    const applyScroll = () => {
      if (hasScrolledToHourRef.current || container.clientHeight === 0) return;
      hasScrolledToHourRef.current = true;
      // Same row height the grid settles on (see updateDimensions above)
      const rowHeight = Math.max(
        MIN_HOUR_HEIGHT,
        container.clientHeight / visibleHourCount,
      );
      const hour = Math.min(Math.max(scrollToHour, dayStartHour), dayEndHour);
      container.scrollTop = (hour - dayStartHour) * rowHeight;
    };

    applyScroll();
    if (hasScrolledToHourRef.current) return;

    const observer = new ResizeObserver(applyScroll);
    observer.observe(container);
    return () => observer.disconnect();
  }, [scrollToHour, dayStartHour, dayEndHour, visibleHourCount]);

  // Track whether navigation was initiated by scroll (to avoid double-animation)
  const scrollNavigatedRef = React.useRef(false);
  const prevDateRef = React.useRef(currentDate);
  const wasProviderInSyncRef = React.useRef(isProviderInSync);

  // Tell the provider which view is on screen. `reportView` changes with the
  // provider's state, so this also re-checks after every switch. A layout
  // effect: the provider adopts this grid before the first paint.
  React.useLayoutEffect(() => {
    reportView({ view, numberOfDays: fixedNumberOfDays });
  }, [view, fixedNumberOfDays, reportView]);

  const handleNavigate = React.useCallback(
    (daysDelta: number) => {
      scrollNavigatedRef.current = true;
      goToDate(addDays(currentDate, daysDelta));
    },
    [currentDate, goToDate],
  );

  const handleDragNavigate = React.useCallback(
    (daysDelta: number) => {
      goToDate(addDays(currentDate, daysDelta));
    },
    [currentDate, goToDate],
  );

  const handleEventClick = React.useCallback(
    (event: CalendarEvent) => selectEvent(event.id),
    [selectEvent],
  );

  const visibleDayDates = React.useMemo(() => days.map((d) => d.date), [days]);

  const { resizeState, handleResizePointerDown } = useEventResize({
    hourHeight,
    scrollContainerRef,
    events: timedEvents,
    days: visibleDayDates,
    dayColumnWidth,
    timeAxisWidth: TIME_AXIS_WIDTH,
    snapMinutes,
    dayStartHour,
    dayEndHour,
    edgeNavigationDays,
    onEventChange: updateEvent,
    onEventClick: handleEventClick,
    onResizeNavigate: handleDragNavigate,
  });

  const { dragState, handleEventPointerDown } = useEventDrag({
    hourHeight,
    scrollContainerRef,
    events: timedEvents,
    days: visibleDayDates,
    dayColumnWidth,
    timeAxisWidth: TIME_AXIS_WIDTH,
    snapMinutes,
    dayStartHour,
    dayEndHour,
    edgeNavigationDays,
    onEventChange: updateEvent,
    onEventClick: handleEventClick,
    onDragNavigate: handleDragNavigate,
  });

  const { scrollOffset, slideOffset, isAnimating, triggerSlideAnimation } =
    useHorizontalScroll({
      containerRef: scrollContainerRef,
      dayColumnWidth,
      onNavigate: handleNavigate,
      disabled:
        dragState?.isDragging ||
        resizeState?.isResizing ||
        isAllDayResizing ||
        contextMenuOpen,
    });

  // Compute how many days the scroll has shifted from center
  const scrollDaysDelta =
    dayColumnWidth > 0 ? Math.round(-scrollOffset / dayColumnWidth) : 0;

  // Report visible days to the provider in real-time as scroll crosses day
  // boundaries. Not while it is adopting this grid: it sets them itself, and
  // these would be the days of the date it is moving away from.
  React.useEffect(() => {
    if (!isProviderInSync) return;
    const start = addDays(currentDate, scrollDaysDelta);
    const end = addDays(start, VISIBLE_DAYS - 1);
    reportVisibleDays(eachDayOfInterval({ start, end }));
  }, [
    isProviderInSync,
    currentDate,
    scrollDaysDelta,
    reportVisibleDays,
    VISIBLE_DAYS,
  ]);

  // Dynamic buffer: extends in BUFFER_STEP chunks based on scroll distance
  const extraScrollDays =
    dayColumnWidth > 0 && BUFFER_STEP > 0
      ? Math.ceil(Math.abs(scrollOffset) / dayColumnWidth / BUFFER_STEP) *
        BUFFER_STEP
      : 0;
  const dynamicBuffer = BUFFER_DAYS + extraScrollDays;
  const totalDays = dynamicBuffer + VISIBLE_DAYS + dynamicBuffer;

  // Extended buffered days for scroll (grows dynamically with scroll distance)
  const bufferedBaseDays = React.useMemo(
    () =>
      generateBufferedDays(currentDate, dynamicBuffer, VISIBLE_DAYS, locale),
    [currentDate, dynamicBuffer, VISIBLE_DAYS, locale],
  );

  const bufferedDays = withIsToday(bufferedBaseDays, today);

  const bufferedDayDates = React.useMemo(
    () => bufferedBaseDays.map((d) => d.date),
    [bufferedBaseDays],
  );

  const { allDayResizeState, handleAllDayResizePointerDown } = useAllDayResize({
    days: bufferedDayDates,
    dayColumnWidth,
    allDayContainerRef: allDayScrollContentRef,
    events: allDayEvents,
    onEventChange: updateEvent,
    onEventClick: handleEventClick,
  });

  React.useEffect(() => {
    setIsAllDayResizing(allDayResizeState?.isResizing ?? false);
  }, [allDayResizeState?.isResizing]);

  // Trigger slide animation when currentDate changes externally (not from scroll)
  React.useEffect(() => {
    const wasProviderInSync = wasProviderInSyncRef.current;
    wasProviderInSyncRef.current = isProviderInSync;

    if (scrollNavigatedRef.current) {
      scrollNavigatedRef.current = false;
      prevDateRef.current = currentDate;
      return;
    }

    const prevDate = prevDateRef.current;
    const daysDiff = differenceInCalendarDays(currentDate, prevDate);
    prevDateRef.current = currentDate;

    if (daysDiff === 0) return;
    // Dates set while the provider adopts this grid (its starting date, or an
    // undone switch) are not navigation
    if (!wasProviderInSync || !isProviderInSync) return;

    triggerSlideAnimation(daysDiff);
  }, [currentDate, isProviderInSync, triggerSlideAnimation]);

  // The base translateX centers on the visible days (skip dynamicBuffer columns)
  const baseTranslateX = -(dynamicBuffer * dayColumnWidth);
  const transformX = baseTranslateX + scrollOffset + slideOffset;

  const scrollStyle: React.CSSProperties = {
    width: `${(totalDays / VISIBLE_DAYS) * 100}%`,
    transform: `translateX(${transformX}px)`,
    transition: isAnimating ? `transform ${200}ms ease-out` : "none",
  };

  // Ref for the popover collision boundary (constrains popovers within the calendar area)
  const calendarBoundaryRef = React.useRef<HTMLDivElement>(null);
  // Ref for the header (weekday columns + all-day row) to measure its height for popover top inset
  const calendarHeaderRef = React.useRef<HTMLDivElement>(null);

  const isDayVisible = React.useCallback(
    (date: Date) => visibleDayDates.some((day) => isSameDay(day, date)),
    [visibleDayDates],
  );

  const revealDay = React.useCallback(
    (date: Date) =>
      goToDate(getPeriodStart(date, view, weekStartsOn, numberOfDays)),
    [goToDate, view, weekStartsOn, numberOfDays],
  );

  const handleEventKeyDown = useEventKeyboard({
    containerRef: calendarBoundaryRef,
    scrollContainerRef,
    isDayVisible,
    revealDay,
  });

  return (
    <CalendarPopoverBoundaryProvider
      boundaryRef={calendarBoundaryRef}
      headerRef={calendarHeaderRef}
      view={view}
    >
      <div
        ref={calendarBoundaryRef}
        className={cn("flex h-full flex-col", className)}
        aria-busy={loading || undefined}
        onKeyDown={handleEventKeyDown}
        onClick={(e) => {
          if (isEventInsideCalendarPopover(e)) return;
          clearSelection();
        }}
      >
        {/* Header - day columns and all-day row with synchronized scroll */}
        <div className="relative flex-shrink-0">
          <div
            ref={(el) => {
              (
                dayColumnsScrollRef as React.MutableRefObject<HTMLDivElement | null>
              ).current = el;
              (
                calendarHeaderRef as React.MutableRefObject<HTMLDivElement | null>
              ).current = el;
            }}
            className="overflow-hidden"
          >
            <div className="flex bg-background">
              {/* Timezone label - rendered outside scroll container */}
              <div className="text-muted-foreground flex w-16 flex-shrink-0 items-center justify-end pr-2 text-xxs">
                {timeZoneLabel}
              </div>
              <div className="min-w-0 flex-1 overflow-clip">
                <div style={scrollStyle}>
                  <CalendarDayHeaders
                    days={bufferedDays}
                    standalone
                    highlightedDate={highlightedDate}
                  />
                </div>
              </div>
            </div>
          </div>
          <div className="overflow-hidden" ref={allDayScrollRef}>
            <WeekViewAllDayRow
              days={bufferedDays}
              allDayEvents={allDayEvents}
              onEventClick={handleEventClick}
              selectedEventId={selectedEventId}
              scrollStyle={scrollStyle}
              allDayResizeState={allDayResizeState ?? undefined}
              onAllDayResizePointerDown={handleAllDayResizePointerDown}
              onEventChange={updateEvent}
              onContextMenuOpenChange={setContextMenuOpen}
              allDayScrollContentRef={allDayScrollContentRef}
              showEventPopover={showEventPopover}
              onEventPopoverExpand={onEventPopoverExpand}
              onEventPopoverClose={closeEventPopover}
              onPrevWeek={goToPrev}
              onNextWeek={goToNext}
              visibleStartIndex={dynamicBuffer}
              visibleCount={VISIBLE_DAYS}
              dayColumnWidth={dayColumnWidth}
              highlightedDate={highlightedDate}
            />
          </div>
          {/* Under the day columns, along the header's bottom border */}
          {loading && <CalendarLoadingBar className="left-16" />}
        </div>

        {/* Scrollable grid area \u2014 also serves as the collision boundary for popovers */}
        <div
          ref={scrollContainerRef}
          className="flex-1 overflow-auto scrollbar-hide"
        >
          <div
            className="relative flex"
            style={{ height: hours.length * hourHeight }}
          >
            <WeekViewTimeAxis hours={hours} hourHeight={hourHeight} />
            {/* Buffer wrappers clip rather than hide: a hidden box can still be
                scrolled by script or the browser (e.g. scrollIntoView before
                an automated click), which would slide the grid out of line
                with the day headers. The buffer only moves by scrollStyle. */}
            <div className="relative min-w-0 flex-1 overflow-clip">
              <div style={scrollStyle}>
                <WeekViewGrid
                  days={bufferedDays}
                  hours={hours}
                  hourHeight={hourHeight}
                  events={timedEvents}
                  onEventClick={handleEventClick}
                  selectedEventId={selectedEventId}
                  onEventCreate={addEventFromRange}
                  dragState={dragState ?? undefined}
                  onEventDragPointerDown={handleEventPointerDown}
                  resizeState={resizeState ?? undefined}
                  onEventResizePointerDown={handleResizePointerDown}
                  onEventChange={updateEvent}
                  onContextMenuOpenChange={setContextMenuOpen}
                  showEventPopover={showEventPopover}
                  onEventPopoverExpand={onEventPopoverExpand}
                  onEventPopoverClose={closeEventPopover}
                  onPrevWeek={goToPrev}
                  onNextWeek={goToNext}
                  highlightedDate={highlightedDate}
                  visibleStartIndex={dynamicBuffer}
                  visibleCount={VISIBLE_DAYS}
                />
              </div>
            </div>
            <WeekViewTimeIndicator
              days={days}
              hourHeight={hourHeight}
              scrollDays={bufferedDays}
              scrollStyle={scrollStyle}
              behindSelection={!!selectedEventId}
            />
          </div>
        </div>
      </div>
    </CalendarPopoverBoundaryProvider>
  );
}

"use client";

import { isSameDay } from "date-fns";
import { cn } from "@/lib/utils";
import { useTimeZoneLabel } from "@/hooks/use-timezone-label";
import type { WeekViewDayColumnsProps } from "./week-view-types";

/**
 * Day column headers showing day names and date numbers
 * Includes timezone label on the left (unless standalone mode)
 * Highlights the current day
 */
export function CalendarDayHeaders({
  days,
  standalone,
  highlightedDate,
  className,
}: WeekViewDayColumnsProps) {
  // Empty on the server and during hydration, the viewer's zone afterwards
  const timezone = useTimeZoneLabel();

  // Standalone mode: just render the day columns (used inside scroll container)
  if (standalone) {
    // Visual only (including the off-screen buffer days): each day column
    // in the grid is labeled with its full date
    return (
      <div
        aria-hidden
        className={cn("grid", className)}
        style={{ gridTemplateColumns: `repeat(${days.length}, 1fr)` }}
      >
        {days.map((day) => (
          <div
            key={day.date.toISOString()}
            className={cn(
              "flex items-center justify-center py-2 text-sm",
              day.isToday ? "gap-0.5 " : "gap-0",
              highlightedDate &&
                isSameDay(day.date, highlightedDate) &&
                "column-highlight",
            )}
          >
            <span
              className={cn(
                day.isToday
                  ? "text-foreground font-medium"
                  : "text-muted-foreground font-normal",
              )}
            >
              {day.dayName}
            </span>
            <span
              className={cn(
                "flex h-5 w-[1.2rem] items-center justify-center rounded-xs text-sm",
                day.isToday
                  ? "bg-primary text-primary-foreground font-medium"
                  : "text-muted-foreground",
              )}
            >
              {day.dayNumber}
            </span>
          </div>
        ))}
      </div>
    );
  }

  return (
    <div
      className={cn("grid bg-background", className)}
      style={{ gridTemplateColumns: "4rem 1fr" }}
    >
      {/* Timezone label */}
      <div className="text-muted-foreground flex items-center justify-end pr-2 text-xxs">
        {timezone}
      </div>

      {/* Day columns */}
      <div
        className="grid"
        style={{ gridTemplateColumns: `repeat(${days.length}, 1fr)` }}
      >
        {days.map((day) => (
          <div
            key={day.date.toISOString()}
            className={cn(
              "flex items-center justify-center py-2 text-sm",
              day.isToday ? "gap-0.5 " : "gap-0",
              highlightedDate &&
                isSameDay(day.date, highlightedDate) &&
                "column-highlight",
            )}
          >
            <span
              className={cn(
                day.isToday
                  ? "text-foreground font-medium"
                  : "text-muted-foreground font-normal",
              )}
            >
              {day.dayName}
            </span>
            <span
              className={cn(
                "flex h-5 w-[1.2rem] items-center justify-center rounded-xs text-sm",
                day.isToday
                  ? "bg-primary text-primary-foreground font-medium"
                  : "text-muted-foreground",
              )}
            >
              {day.dayNumber}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import type React from "react";
import { createPortal } from "react-dom";
import { cn } from "@/lib/utils";
import { isSameDay } from "date-fns";
import { useCallback } from "react";
import { calculateAllDayEventRows } from "@/lib/event-utils";
import { AllDayEventItem } from "./calendar-event-item";
import { useCalendarPopoverBoundary } from "./calendar-popover-context";
import type {
  CalendarEvent,
  EventItemPopoverProps,
  WeekViewAllDayRowProps,
} from "./week-view-types";

const ALL_DAY_EVENT_HEIGHT = 24;
const ALL_DAY_ROW_GAP = 2;

/**
 * All-day row for displaying all-day events
 * Shows "All-day" label on the left with day columns
 */
export function WeekViewAllDayRow({
  days,
  allDayEvents = [],
  onEventClick,
  selectedEventId,
  scrollStyle,
  allDayResizeState,
  onAllDayResizePointerDown,
  allDayScrollContentRef,
  onEventChange,
  onContextMenuOpenChange,
  showEventPopover,
  onEventPopoverExpand,
  onEventPopoverClose,
  onPrevWeek,
  onNextWeek,
  visibleStartIndex,
  visibleCount,
  dayColumnWidth,
  highlightedDate,
  className,
}: WeekViewAllDayRowProps) {
  const allEventRows = calculateAllDayEventRows(allDayEvents, days);

  // Filter out events entirely within buffer columns so they don't peek
  // through due to sub-pixel rendering at the scroll boundary.
  const visibleEnd =
    visibleStartIndex != null && visibleCount != null
      ? visibleStartIndex + visibleCount - 1
      : days.length - 1;
  const eventRows =
    visibleStartIndex != null
      ? allEventRows.filter(
          ({ startColumn, endColumn }) =>
            endColumn >= visibleStartIndex && startColumn <= visibleEnd,
        )
      : allEventRows;
  const maxRow =
    eventRows.length > 0 ? Math.max(...eventRows.map((r) => r.row)) + 1 : 0;
  const contentHeight =
    maxRow > 0 ? maxRow * (ALL_DAY_EVENT_HEIGHT + ALL_DAY_ROW_GAP) + 8 : 32;

  const isMoveDrag =
    allDayResizeState?.isResizing && allDayResizeState.edge === "move";

  return (
    <div
      className={cn(
        "border-border flex border-t border-b bg-background",
        className,
      )}
    >
      {/* All-day label */}
      <div className="border-border text-muted-foreground flex w-16 flex-shrink-0 items-start justify-end border-r px-2 py-2 text-xxs">
        All-day
      </div>

      {/* Day columns for all-day events - wrapped for scroll sync */}
      <div className="min-w-0 flex-1 overflow-clip">
        <div ref={allDayScrollContentRef} style={scrollStyle}>
          <div className="relative" style={{ minHeight: `${contentHeight}px` }}>
            {/* Background grid */}
            <div
              aria-hidden
              className="absolute inset-0 grid"
              style={{ gridTemplateColumns: `repeat(${days.length}, 1fr)` }}
            >
              {days.map((day) => {
                const isWeekend =
                  day.date.getDay() === 0 || day.date.getDay() === 6;
                return (
                  <div
                    key={day.date.toISOString()}
                    className={cn(
                      "border-border border-l first:border-l-0 h-full",
                      isWeekend && "bg-calendar-weekend",
                      highlightedDate &&
                        isSameDay(day.date, highlightedDate) &&
                        "column-highlight",
                    )}
                  />
                );
              })}
            </div>

            {/* Events */}
            <div className="relative py-1 px-0.5">
              {eventRows.map(({ event, startColumn, endColumn, row }) => {
                const isBeingResized =
                  allDayResizeState?.eventId === event.id &&
                  allDayResizeState.isResizing;
                const isBeingMoved =
                  isBeingResized && allDayResizeState.edge === "move";

                // For move: ghost stays at original, event renders at target
                // For resize: event renders at target (current columns)
                const displayStartColumn = isBeingResized
                  ? isBeingMoved
                    ? startColumn
                    : allDayResizeState.currentStartColumn
                  : startColumn;
                const displayEndColumn = isBeingResized
                  ? isBeingMoved
                    ? endColumn
                    : allDayResizeState.currentEndColumn
                  : endColumn;

                return (
                  <AllDayEventRow
                    key={event.id}
                    event={event}
                    startColumn={displayStartColumn}
                    endColumn={displayEndColumn}
                    row={row}
                    totalColumns={days.length}
                    days={days}
                    onEventClick={onEventClick}
                    isSelected={event.id === selectedEventId}
                    onAllDayResizePointerDown={onAllDayResizePointerDown}
                    originalStartColumn={startColumn}
                    originalEndColumn={endColumn}
                    isBeingResized={isBeingResized}
                    isBeingMoved={isBeingMoved}
                    onEventChange={onEventChange}
                    onContextMenuOpenChange={onContextMenuOpenChange}
                    showEventPopover={showEventPopover}
                    onEventPopoverExpand={onEventPopoverExpand}
                    onEventPopoverClose={onEventPopoverClose}
                    onPrevWeek={onPrevWeek}
                    onNextWeek={onNextWeek}
                    visibleStartIndex={visibleStartIndex}
                  />
                );
              })}

              {/* Placeholder at target position during move */}
              {isMoveDrag &&
                (() => {
                  const movedRow = eventRows.find(
                    (r) => r.event.id === allDayResizeState.eventId,
                  );
                  if (!movedRow) return null;
                  return (
                    <AllDayPlaceholderRow
                      event={movedRow.event}
                      startColumn={allDayResizeState.currentStartColumn}
                      endColumn={allDayResizeState.currentEndColumn}
                      row={movedRow.row}
                      totalColumns={days.length}
                    />
                  );
                })()}
            </div>
          </div>
        </div>
      </div>

      {/* Floating drag copy via portal */}
      {isMoveDrag &&
        allDayResizeState.clientX != null &&
        allDayResizeState.clientY != null &&
        (() => {
          const movedRow = eventRows.find(
            (r) => r.event.id === allDayResizeState.eventId,
          );
          if (!movedRow) return null;
          const span = movedRow.endColumn - movedRow.startColumn + 1;
          const colWidthPx = dayColumnWidth ?? 100;
          const floatingWidth = span * colWidthPx;
          const offsetX = allDayResizeState.cursorOffsetX ?? 0;

          return createPortal(
            <div
              aria-hidden
              className="pointer-events-none"
              style={{
                position: "fixed",
                top: 0,
                left: 0,
                width: "100vw",
                height: "100vh",
                zIndex: 9999,
              }}
            >
              <div
                style={{
                  position: "fixed",
                  left: `${allDayResizeState.clientX - offsetX}px`,
                  top: `${allDayResizeState.clientY - (allDayResizeState.cursorOffsetY ?? 12)}px`,
                  width: `${floatingWidth}px`,
                }}
              >
                <AllDayEventItem
                  event={movedRow.event}
                  spanStart
                  spanEnd
                  dragVariant="dragging"
                />
              </div>
            </div>,
            document.body,
          );
        })()}
    </div>
  );
}

interface AllDayEventRowProps extends EventItemPopoverProps {
  event: CalendarEvent;
  startColumn: number;
  endColumn: number;
  row: number;
  totalColumns: number;
  days: WeekViewAllDayRowProps["days"];
  onEventClick?: (event: CalendarEvent) => void;
  isSelected?: boolean;
  onAllDayResizePointerDown?: WeekViewAllDayRowProps["onAllDayResizePointerDown"];
  originalStartColumn: number;
  originalEndColumn: number;
  isBeingResized?: boolean;
  isBeingMoved?: boolean;
  /** Callback when an event is changed (e.g. color change from context menu) */
  onEventChange?: (event: CalendarEvent) => void;
  /** Callback when context menu open state changes */
  onContextMenuOpenChange?: (open: boolean) => void;
  /** Index of the first visible column (for sticky-title offset) */
  visibleStartIndex?: number;
}

function AllDayEventRow({
  event,
  startColumn,
  endColumn,
  row,
  totalColumns,
  days,
  onEventClick,
  isSelected,
  onAllDayResizePointerDown,
  originalStartColumn,
  originalEndColumn,
  isBeingResized,
  isBeingMoved,
  onEventChange,
  onContextMenuOpenChange,
  showEventPopover,
  onEventPopoverExpand,
  onEventPopoverClose,
  onPrevWeek,
  onNextWeek,
  visibleStartIndex,
}: AllDayEventRowProps) {
  const { view } = useCalendarPopoverBoundary();
  const isDayView = view === "day";

  const left = (startColumn / totalColumns) * 100;
  // Day view uses a smaller right gap than week view so events nearly fill
  // the column but still show a sliver of the grid \u2014 matching Notion Calendar.
  const columnWidth = 100 / totalColumns;
  const rightGap = isDayView ? columnWidth * 0.02 : columnWidth * 0.08;
  const width = ((endColumn - startColumn + 1) / totalColumns) * 100 - rightGap;
  const top = row * (ALL_DAY_EVENT_HEIGHT + ALL_DAY_ROW_GAP);

  // During resize, both edges are always visible so force rounding on both sides
  const spanStart =
    isBeingResized || isSameDay(event.start, days[startColumn].date);
  const spanEnd = isBeingResized || isSameDay(event.end, days[endColumn].date);

  /**
   * In day view with buffer days (3 columns: buffer | visible | buffer),
   * the visible column is index 1. Multi-day events that start in the left
   * buffer (column 0) have their title off-screen. Calculate the percentage
   * offset needed to push the title into the visible area.
   *
   * CSS `padding-left` percentages are relative to the **containing block's
   * width** (the wrapper div), not the grid container. We must convert from
   * container-relative coordinates to wrapper-relative coordinates:
   *   offset = (visibleStart% - left%) \u00D7 (100 / width%)
   */
  const visibleColumnIndex = visibleStartIndex ?? 1;
  const visibleStartPercent = (visibleColumnIndex / totalColumns) * 100;
  const hiddenContainerPercent = isDayView
    ? Math.max(0, visibleStartPercent - left)
    : 0;
  /** Small extra nudge (in container %) so the title doesn't sit flush
   *  against the visible column edge \u2014 gives it a bit of breathing room. */
  const TITLE_NUDGE_PERCENT = 0.1;
  const titleOffsetPercent =
    hiddenContainerPercent > 0 && width > 0
      ? ((hiddenContainerPercent + TITLE_NUDGE_PERCENT) / width) * 100
      : 0;

  const handleResizePointerDown = useCallback(
    (
      e: React.PointerEvent<HTMLElement>,
      ev: CalendarEvent,
      edge: "left" | "right" | "move",
    ) => {
      onAllDayResizePointerDown?.(
        e,
        ev,
        edge,
        originalStartColumn,
        originalEndColumn,
      );
    },
    [onAllDayResizePointerDown, originalStartColumn, originalEndColumn],
  );

  return (
    <div
      className="absolute"
      style={{
        left: `${left}%`,
        width: `${width}%`,
        top: `${top}px`,
        paddingLeft: "2px",
        paddingRight: "2px",
      }}
    >
      <AllDayEventItem
        event={event}
        isSelected={isBeingMoved ? false : isSelected}
        onClick={onEventClick}
        spanStart={spanStart}
        spanEnd={spanEnd}
        onResizePointerDown={handleResizePointerDown}
        onEventChange={onEventChange}
        onContextMenuOpenChange={onContextMenuOpenChange}
        showEventPopover={showEventPopover}
        onEventPopoverExpand={onEventPopoverExpand}
        onEventPopoverClose={onEventPopoverClose}
        onPrevWeek={onPrevWeek}
        onNextWeek={onNextWeek}
        titleOffsetPercent={titleOffsetPercent}
        dragVariant={isBeingMoved ? "ghost" : undefined}
        isResizing={isBeingResized && !isBeingMoved}
      />
    </div>
  );
}

/** Placeholder border-only outline rendered at the target position during move */
function AllDayPlaceholderRow({
  event,
  startColumn,
  endColumn,
  row,
  totalColumns,
}: {
  event: CalendarEvent;
  startColumn: number;
  endColumn: number;
  row: number;
  totalColumns: number;
}) {
  const columnWidth = 100 / totalColumns;
  const left = (startColumn / totalColumns) * 100;
  const rightGap = columnWidth * 0.08;
  const width = ((endColumn - startColumn + 1) / totalColumns) * 100 - rightGap;
  const top = row * (ALL_DAY_EVENT_HEIGHT + ALL_DAY_ROW_GAP);

  return (
    <div
      aria-hidden
      className="absolute pointer-events-none"
      style={{
        left: `${left}%`,
        width: `${width}%`,
        top: `${top}px`,
        paddingLeft: "2px",
        paddingRight: "2px",
        zIndex: 25,
      }}
    >
      <AllDayEventItem
        event={event}
        spanStart
        spanEnd
        dragVariant="placeholder"
      />
    </div>
  );
}

"use client";

import React from "react";
import { createPortal } from "react-dom";
import { isSameDay, startOfDay, addDays } from "date-fns";
import { cn } from "@/lib/utils";
import { isPrimaryPress, usePointerGesture } from "@/hooks/use-pointer-gesture";
import {
  calculatePositionedEvents,
  formatFullDate,
  getNewEventRange,
} from "@/lib/event-utils";
import { CalendarEventItem } from "./calendar-event-item";
import { useCalendarPopoverBoundary } from "./calendar-popover-context";
import { useCalendarConfig } from "./calendar-provider";
import type {
  CalendarEvent,
  EventDragState,
  EventItemPopoverProps,
  EventResizeState,
  PositionedEvent,
  WeekViewGridProps,
} from "./week-view-types";

/**
 * Max pointer travel (px) between pointerdown and click for a click on an
 * empty slot to create an event. Matches the drag threshold in
 * use-event-drag so a press that moves far enough to count as a drag never
 * also creates an event.
 */
const CREATE_CLICK_TOLERANCE_PX = 4;

/** Pointer position recorded when a mouse or pen press lands on an empty day column */
interface PendingCreateClick {
  clientX: number;
  clientY: number;
}

/**
 * Main grid displaying hour/day intersection cells with events
 * Each cell represents one hour in one day
 */
export function WeekViewGrid({
  days,
  hours,
  hourHeight,
  events = [],
  onEventClick,
  selectedEventId,
  onEventCreate,
  dragState,
  onEventDragPointerDown,
  resizeState,
  onEventResizePointerDown,
  onEventChange,
  onContextMenuOpenChange,
  showEventPopover,
  onEventPopoverExpand,
  onEventPopoverClose,
  onPrevWeek,
  onNextWeek,
  highlightedDate,
  visibleStartIndex = 0,
  visibleCount,
  className,
}: WeekViewGridProps) {
  const { view } = useCalendarPopoverBoundary();
  const config = useCalendarConfig();
  const isDayView = view === "day";
  const gridRef = React.useRef<HTMLDivElement>(null);
  /** Set only by a mouse or pen press directly on empty column space */
  const pendingCreateRef = React.useRef<PendingCreateClick | null>(null);
  const [gridWidth, setGridWidth] = React.useState(0);
  const { startGesture } = usePointerGesture({ containerRef: gridRef });

  React.useEffect(() => {
    const el = gridRef.current;
    if (!el) return;

    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        setGridWidth(entry.contentRect.width);
      }
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  /** Creates an event in a column at a viewport Y position */
  const createEventAt = React.useCallback(
    (column: HTMLElement, columnDate: Date, clientY: number) => {
      if (!onEventCreate) return;
      // The column's top edge is `dayStartHour`, not midnight
      const columnTop = column.getBoundingClientRect().top;
      const minutesFromMidnight =
        config.dayStartHour * 60 + ((clientY - columnTop) / hourHeight) * 60;
      onEventCreate(getNewEventRange(columnDate, minutesFromMidnight, config));
    },
    [onEventCreate, hourHeight, config],
  );

  /**
   * Capture phase runs before event items stop pointerdown propagation, so
   * a press that starts on an event (drag, resize, select) always clears any
   * pending create left over from an earlier press.
   */
  const handleColumnPointerDownCapture = React.useCallback(() => {
    pendingCreateRef.current = null;
  }, []);

  const handleColumnPointerDown = React.useCallback(
    (e: React.PointerEvent<HTMLDivElement>, columnDate: Date) => {
      if (e.target !== e.currentTarget) return;
      // Touch creates with a long press, so a swipe over empty space still
      // scrolls and a tap only clears the selection
      if (e.pointerType === "touch") {
        startGesture(e, ({ clientY, element }) =>
          createEventAt(element, columnDate, clientY),
        );
        return;
      }
      if (!isPrimaryPress(e)) return;
      pendingCreateRef.current = { clientX: e.clientX, clientY: e.clientY };
    },
    [startGesture, createEventAt],
  );

  /**
   * Creates an event when a press started and ended on empty space in the
   * same column without moving. With an event selected the click is left to
   * bubble so WeekView's background click deselects instead.
   */
  const handleColumnClick = React.useCallback(
    (e: React.MouseEvent<HTMLDivElement>, columnDate: Date) => {
      const pending = pendingCreateRef.current;
      pendingCreateRef.current = null;

      if (!pending || !onEventCreate) return;
      if (e.target !== e.currentTarget) return;
      if (selectedEventId) return;

      const movedX = Math.abs(e.clientX - pending.clientX);
      const movedY = Math.abs(e.clientY - pending.clientY);
      if (
        movedX > CREATE_CLICK_TOLERANCE_PX ||
        movedY > CREATE_CLICK_TOLERANCE_PX
      ) {
        return;
      }

      e.stopPropagation();
      createEventAt(e.currentTarget, columnDate, e.clientY);
    },
    [onEventCreate, selectedEventId, createEventAt],
  );

  return (
    <div ref={gridRef} className={cn("relative", className)}>
      {/* Background grid */}
      <div
        aria-hidden
        className="grid"
        style={{
          gridTemplateColumns: `repeat(${days.length}, 1fr)`,
          gridTemplateRows: `repeat(${hours.length}, ${hourHeight}px)`,
        }}
      >
        {hours.map((hourSlot) =>
          days.map((day) => {
            const isWeekend =
              day.date.getDay() === 0 || day.date.getDay() === 6;
            return (
              <div
                key={`${day.date.toISOString()}-${hourSlot.hour}`}
                className={cn(
                  "border-border border-b border-l",
                  isWeekend && "bg-calendar-weekend",
                )}
              />
            );
          }),
        )}
      </div>

      {/* Column highlight layer — brief background fade for "+N more" navigation */}
      {highlightedDate && (
        <div
          aria-hidden
          className="absolute inset-0 grid pointer-events-none"
          style={{ gridTemplateColumns: `repeat(${days.length}, 1fr)` }}
        >
          {days.map((day) => (
            <div
              key={day.date.toISOString()}
              className={cn(
                isSameDay(day.date, highlightedDate) && "column-highlight",
              )}
            />
          ))}
        </div>
      )}

      {/* Events layer */}
      <div
        className="absolute inset-0 grid pointer-events-none"
        style={{ gridTemplateColumns: `repeat(${days.length}, 1fr)` }}
      >
        {days.map((day, index) => {
          const isOnScreen =
            index >= visibleStartIndex &&
            index < visibleStartIndex + (visibleCount ?? days.length);
          /**
           * Day view uses a smaller right gap than week view so events
           * nearly fill the column but still show a sliver of the grid
           * line — matching Notion Calendar's day-view styling.
           */
          const rightGap = isDayView ? 2 : 8;
          const positionedEvents = calculatePositionedEvents(
            events,
            day,
            config,
            rightGap,
          );

          return (
            <DayEventsColumn
              key={day.date.toISOString()}
              columnDate={day.date}
              label={formatFullDate(day.date, config.locale)}
              isOnScreen={isOnScreen}
              events={positionedEvents}
              hourHeight={hourHeight}
              onEventClick={onEventClick}
              selectedEventId={selectedEventId}
              dragState={dragState}
              onEventDragPointerDown={onEventDragPointerDown}
              resizeState={resizeState}
              onEventResizePointerDown={onEventResizePointerDown}
              onEventChange={onEventChange}
              onContextMenuOpenChange={onContextMenuOpenChange}
              showEventPopover={showEventPopover}
              onEventPopoverExpand={onEventPopoverExpand}
              onEventPopoverClose={onEventPopoverClose}
              onPrevWeek={onPrevWeek}
              onNextWeek={onNextWeek}
              onColumnPointerDownCapture={handleColumnPointerDownCapture}
              onColumnPointerDown={handleColumnPointerDown}
              onColumnClick={handleColumnClick}
            />
          );
        })}
      </div>

      {/* Resize placeholder overlay — rendered at grid level for cross-day support */}
      {resizeState?.isResizing &&
        !isSameDay(
          resizeState.currentStartDate,
          resizeState.currentEndDate,
        ) && (
          <ResizePlaceholderOverlay
            days={days}
            hourHeight={hourHeight}
            resizeState={resizeState}
          />
        )}

      {/* Drag placeholder overlay — rendered at grid level for cross-column support */}
      {dragState?.isDragging && (
        <DragPlaceholderOverlay
          days={days}
          hourHeight={hourHeight}
          dragState={dragState}
        />
      )}

      {/* Floating dragging copy — rendered at grid level so it can move freely */}
      {dragState?.isDragging && (
        <FloatingDragCopy
          days={days}
          hourHeight={hourHeight}
          dragState={dragState}
          gridWidth={gridWidth}
        />
      )}
    </div>
  );
}

interface DragPlaceholderOverlayProps {
  days: WeekViewGridProps["days"];
  hourHeight: number;
  dragState: EventDragState;
}

function DragPlaceholderOverlay({
  days,
  hourHeight,
  dragState,
}: DragPlaceholderOverlayProps) {
  // Find the target column index using dragState.currentDate
  const targetColumnIndex = days.findIndex((d) =>
    isSameDay(d.date, dragState.currentDate),
  );

  if (targetColumnIndex === -1) return null;

  // Build a minimal PositionedEvent from the drag state event
  const placeholderPositioned: PositionedEvent = {
    event: dragState.event,
    top: 0,
    height: 0,
    left: 0,
    width: 92,
    column: 0,
    totalColumns: 1,
  };

  return (
    <div
      aria-hidden
      className="absolute inset-0 grid pointer-events-none"
      style={{ gridTemplateColumns: `repeat(${days.length}, 1fr)` }}
    >
      {days.map((day, i) => {
        if (i !== targetColumnIndex) {
          return <div key={day.date.toISOString()} />;
        }

        return (
          <div key={day.date.toISOString()} className="relative">
            <CalendarEventItem
              key={`${dragState.eventId}-placeholder`}
              positionedEvent={placeholderPositioned}
              hourHeight={hourHeight}
              dragVariant="placeholder"
              overrideStart={dragState.currentStart}
              overrideEnd={dragState.currentEnd}
            />
          </div>
        );
      })}
    </div>
  );
}

interface ResizePlaceholderOverlayProps {
  days: WeekViewGridProps["days"];
  hourHeight: number;
  resizeState: EventResizeState;
}

function ResizePlaceholderOverlay({
  days,
  hourHeight,
  resizeState,
}: ResizePlaceholderOverlayProps) {
  if (resizeState.effectiveEdge === "bottom") {
    return (
      <BottomEdgeOverlay
        days={days}
        hourHeight={hourHeight}
        resizeState={resizeState}
      />
    );
  }

  return (
    <TopEdgeOverlay
      days={days}
      hourHeight={hourHeight}
      resizeState={resizeState}
    />
  );
}

function BottomEdgeOverlay({
  days,
  hourHeight,
  resizeState,
}: ResizePlaceholderOverlayProps) {
  const endDay = resizeState.currentEndDate;

  const startColIndex = days.findIndex((d) =>
    isSameDay(d.date, resizeState.currentStartDate),
  );
  const endColIndex = days.findIndex((d) => isSameDay(d.date, endDay));

  if (startColIndex === -1 || endColIndex === -1) return null;
  if (endColIndex <= startColIndex) return null;

  return (
    <div
      aria-hidden
      className="absolute inset-0 grid pointer-events-none"
      style={{ gridTemplateColumns: `repeat(${days.length}, 1fr)` }}
    >
      {days.map((day, i) => {
        // Skip start column (handled by DayEventsColumn) and columns outside range
        if (i <= startColIndex || i > endColIndex) {
          return <div key={day.date.toISOString()} />;
        }

        const isEndColumn = i === endColIndex;
        const segmentPosition = isEndColumn
          ? ("end" as const)
          : ("middle" as const);

        const midnight = startOfDay(day.date);
        const overrideStart = midnight;
        const overrideEnd = isEndColumn
          ? resizeState.currentEnd
          : addDays(midnight, 1);

        const positioned: PositionedEvent = {
          event: resizeState.event,
          top: 0,
          height: 0,
          left: 0,
          width: 92,
          column: 0,
          totalColumns: 1,
          segmentPosition,
        };

        return (
          <div key={day.date.toISOString()} className="relative">
            <CalendarEventItem
              positionedEvent={positioned}
              hourHeight={hourHeight}
              isSelected
              isResizing
              overrideStart={overrideStart}
              overrideEnd={overrideEnd}
            />
          </div>
        );
      })}
    </div>
  );
}

function TopEdgeOverlay({
  days,
  hourHeight,
  resizeState,
}: ResizePlaceholderOverlayProps) {
  const startDay = resizeState.currentStartDate;

  const startColIndex = days.findIndex((d) => isSameDay(d.date, startDay));
  const endColIndex = days.findIndex((d) =>
    isSameDay(d.date, resizeState.currentEndDate),
  );

  if (startColIndex === -1 || endColIndex === -1) return null;
  if (endColIndex <= startColIndex) return null;

  return (
    <div
      aria-hidden
      className="absolute inset-0 grid pointer-events-none"
      style={{ gridTemplateColumns: `repeat(${days.length}, 1fr)` }}
    >
      {days.map((day, i) => {
        // Skip end column (handled by DayEventsColumn) and columns outside range
        if (i < startColIndex || i >= endColIndex) {
          return <div key={day.date.toISOString()} />;
        }

        const isStartColumn = i === startColIndex;
        const segmentPosition = isStartColumn
          ? ("start" as const)
          : ("middle" as const);

        const midnight = startOfDay(day.date);
        const overrideStart = isStartColumn
          ? resizeState.currentStart
          : midnight;
        const overrideEnd = addDays(midnight, 1);

        const positioned: PositionedEvent = {
          event: resizeState.event,
          top: 0,
          height: 0,
          left: 0,
          width: 92,
          column: 0,
          totalColumns: 1,
          segmentPosition,
        };

        return (
          <div key={day.date.toISOString()} className="relative">
            <CalendarEventItem
              positionedEvent={positioned}
              hourHeight={hourHeight}
              isSelected
              isResizing
              overrideStart={overrideStart}
              overrideEnd={overrideEnd}
            />
          </div>
        );
      })}
    </div>
  );
}

interface FloatingDragCopyProps {
  days: WeekViewGridProps["days"];
  hourHeight: number;
  dragState: EventDragState;
  gridWidth: number;
}

function FloatingDragCopy({
  days,
  hourHeight,
  dragState,
  gridWidth,
}: FloatingDragCopyProps) {
  const floatingPositioned: PositionedEvent = {
    event: dragState.event,
    top: 0,
    height: 0,
    left: 0,
    width: 92,
    column: 0,
    totalColumns: 1,
  };

  const durationMinutes =
    (dragState.currentEnd.getTime() - dragState.currentStart.getTime()) / 60000;
  const heightPx = (durationMinutes / 60) * hourHeight;
  const columnWidthPx =
    (days.length > 0 ? gridWidth / days.length : 200) * 0.92;

  return createPortal(
    <div
      aria-hidden
      className="pointer-events-none"
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        width: "100vw",
        height: "100vh",
        zIndex: 9999,
      }}
    >
      <CalendarEventItem
        key={`${dragState.eventId}-dragging`}
        positionedEvent={floatingPositioned}
        hourHeight={hourHeight}
        dragVariant="dragging"
        overrideStart={dragState.currentStart}
        overrideEnd={dragState.currentEnd}
        cursorY={dragState.clientY}
        cursorX={dragState.clientX}
        fixedWidth={columnWidthPx}
        fixedHeight={heightPx}
      />
    </div>,
    document.body,
  );
}

interface DayEventsColumnProps extends EventItemPopoverProps {
  columnDate: Date;
  /** Accessible name: the column's full date */
  label: string;
  /**
   * Whether the column is on screen. Off-screen scroll buffer columns are
   * inert, so their events can't be tabbed to or read out.
   */
  isOnScreen: boolean;
  events: ReturnType<typeof calculatePositionedEvents>;
  hourHeight: number;
  onEventClick?: (event: CalendarEvent) => void;
  selectedEventId?: string;
  dragState?: EventDragState;
  onEventDragPointerDown?: WeekViewGridProps["onEventDragPointerDown"];
  resizeState?: EventResizeState;
  onEventResizePointerDown?: WeekViewGridProps["onEventResizePointerDown"];
  onEventChange?: (event: CalendarEvent) => void;
  onContextMenuOpenChange?: (open: boolean) => void;
  onColumnPointerDownCapture?: () => void;
  onColumnPointerDown?: (
    e: React.PointerEvent<HTMLDivElement>,
    columnDate: Date,
  ) => void;
  onColumnClick?: (
    e: React.MouseEvent<HTMLDivElement>,
    columnDate: Date,
  ) => void;
}

function renderColumnGhost(
  positionedEvent: PositionedEvent,
  hourHeight: number,
) {
  return (
    <CalendarEventItem
      key={`${positionedEvent.event.id}-ghost`}
      positionedEvent={positionedEvent}
      hourHeight={hourHeight}
      dragVariant="ghost"
    />
  );
}

function DayEventsColumn({
  columnDate,
  label,
  isOnScreen,
  events,
  hourHeight,
  onEventClick,
  selectedEventId,
  dragState,
  onEventDragPointerDown,
  resizeState,
  onEventResizePointerDown,
  onEventChange,
  onContextMenuOpenChange,
  showEventPopover,
  onEventPopoverExpand,
  onEventPopoverClose,
  onPrevWeek,
  onNextWeek,
  onColumnPointerDownCapture,
  onColumnPointerDown,
  onColumnClick,
}: DayEventsColumnProps) {
  return (
    <div
      role="group"
      aria-label={label}
      inert={!isOnScreen}
      className="relative h-full pointer-events-auto"
      onPointerDownCapture={onColumnPointerDownCapture}
      onPointerDown={(e) => onColumnPointerDown?.(e, columnDate)}
      onClick={(e) => onColumnClick?.(e, columnDate)}
    >
      {events.map((positionedEvent) => {
        const eventId = positionedEvent.event.id;
        const isBeingDragged =
          dragState?.isDragging && dragState.eventId === eventId;

        if (isBeingDragged) {
          return renderColumnGhost(positionedEvent, hourHeight);
        }

        const isBeingResized =
          resizeState?.isResizing && resizeState.eventId === eventId;

        if (isBeingResized) {
          const { effectiveEdge, currentStartDate, currentEndDate } =
            resizeState;
          const isCrossDay = !isSameDay(currentStartDate, currentEndDate);

          // Determine if this column is the anchor column
          const isAnchorColumn =
            (effectiveEdge === "bottom" &&
              isSameDay(columnDate, currentStartDate)) ||
            (effectiveEdge === "top" && isSameDay(columnDate, currentEndDate));

          // Check if this column is within the new range at all
          const colTime = columnDate.getTime();
          const inRange =
            colTime >= currentStartDate.getTime() &&
            colTime <= currentEndDate.getTime();

          // Non-anchor columns with original segments: render as ghost
          // Columns outside new range with original segments: render as ghost
          if (!isAnchorColumn || !inRange) {
            return renderColumnGhost(positionedEvent, hourHeight);
          }

          // Anchor column rendering
          let displayStart: Date;
          let displayEnd: Date;
          let segmentPosition: "start" | "middle" | "end" | "full";

          if (!isCrossDay) {
            // Same day: show currentStart to currentEnd
            displayStart = resizeState.currentStart;
            displayEnd = resizeState.currentEnd;
            segmentPosition = "full";
          } else if (effectiveEdge === "bottom") {
            // Anchor is start column: show currentStart to end-of-day
            displayStart = resizeState.currentStart;
            displayEnd = addDays(startOfDay(columnDate), 1);
            segmentPosition = "start";
          } else {
            // Anchor is end column: show start-of-day to currentEnd
            displayStart = startOfDay(columnDate);
            displayEnd = resizeState.currentEnd;
            segmentPosition = "end";
          }

          const resizePositioned = { ...positionedEvent, segmentPosition };

          return (
            <React.Fragment key={eventId}>
              {renderColumnGhost(positionedEvent, hourHeight)}
              <CalendarEventItem
                key={`${eventId}-resizing`}
                positionedEvent={resizePositioned}
                hourHeight={hourHeight}
                isSelected={isCrossDay || eventId === selectedEventId}
                isResizing
                overrideStart={displayStart}
                overrideEnd={displayEnd}
                onEventChange={onEventChange}
              />
            </React.Fragment>
          );
        }

        return (
          <CalendarEventItem
            key={eventId}
            positionedEvent={positionedEvent}
            hourHeight={hourHeight}
            isSelected={eventId === selectedEventId}
            onClick={onEventClick}
            onDragPointerDown={onEventDragPointerDown}
            onResizePointerDown={onEventResizePointerDown}
            onEventChange={onEventChange}
            onContextMenuOpenChange={onContextMenuOpenChange}
            showEventPopover={showEventPopover}
            onEventPopoverExpand={onEventPopoverExpand}
            onEventPopoverClose={onEventPopoverClose}
            onPrevWeek={onPrevWeek}
            onNextWeek={onNextWeek}
          />
        );
      })}
    </div>
  );
}

