"use client";

import { format } from "date-fns";
import * as React from "react";

import { cn } from "@/lib/utils";
import { useNow } from "@/hooks/use-now";
import { useCalendarConfig } from "./calendar-provider";
import type { WeekViewTimeIndicatorProps } from "./week-view-types";

/**
 * Current time indicator showing time badge and horizontal lines
 * - Time badge with current time (e.g., "5:48PM", or "17:48" on a 24-hour clock) on the left
 * - Thick line on today's column
 * - Thin line on other day columns
 * Moves on every minute boundary via the shared `useNow` clock. Renders
 * nothing on the server and during hydration, where the time is unknown,
 * and outside the visible hours (`dayStartHour` to `dayEndHour`).
 */
export function WeekViewTimeIndicator({
  days,
  hourHeight,
  scrollDays,
  scrollStyle,
  behindSelection,
  className,
}: WeekViewTimeIndicatorProps) {
  const currentTime = useNow();
  const { dayStartHour, dayEndHour, hourCycle, locale } = useCalendarConfig();

  // Check if today is visible in the current week
  const isTodayVisible = days.some((day) => day.isToday);

  if (!currentTime || !isTodayVisible) {
    return null;
  }

  // Calculate position based on current time, from the grid's top edge
  const minutesSinceMidnight =
    currentTime.getHours() * 60 + currentTime.getMinutes();
  const visibleStartMinutes = dayStartHour * 60;
  if (
    minutesSinceMidnight < visibleStartMinutes ||
    minutesSinceMidnight >= dayEndHour * 60
  ) {
    return null;
  }
  const topPosition =
    ((minutesSinceMidnight - visibleStartMinutes) / 60) * hourHeight;

  // "5:48PM" on a 12-hour clock, "17:48" on a 24-hour clock
  const formattedTime =
    hourCycle === 24
      ? format(currentTime, "HH:mm", { locale })
      : format(currentTime, "h:mma", { locale }).toUpperCase();

  const lineDays = scrollDays ?? days;
  const lineTodayIndex = lineDays.findIndex((d) => d.isToday);

  const linesContent = (
    <div className="flex items-center">
      {lineDays.map((day, index) => (
        <React.Fragment key={day.date.toISOString()}>
          {index === lineTodayIndex && (
            <div className="relative flex-shrink-0">
              <div className="bg-primary h-3 w-[3px] translate-y-[0.5px] rounded-full shadow-[0_0_0_1px_white] dark:shadow-[0_0_0_1px_black]" />
              <div className="absolute top-[6.5px] left-[2px] bg-primary h-[1px] w-[2px] z-10" />
              <div className="absolute top-[5.5px] left-[2px] bg-primary h-[1px] w-[2px] z-10" />
              <div className="absolute top-[4.5px] left-[2px] bg-primary h-[1px] w-[2px] z-10" />
            </div>
          )}
          <div
            className={cn(
              "flex-1 bg-primary",
              day.isToday
                ? "h-[3px] rounded-r-full shadow-[0_0_0_1px_white] dark:shadow-[0_0_0_1px_black]"
                : "h-[0.5px]",
            )}
          />
        </React.Fragment>
      ))}
    </div>
  );

  return (
    <div
      aria-hidden
      className={cn(
        "pointer-events-none absolute left-0 right-0",
        behindSelection ? "z-10" : "z-20",
        className,
      )}
      style={{ top: topPosition }}
    >
      <div className="flex -translate-y-1/2 items-center">
        {/* Time badge - positioned in the time axis area */}
        <div className="flex w-16 flex-shrink-0 items-center justify-end pr-1">
          <span className="bg-primary text-primary-foreground rounded-xs px-1 py-0.5 text-xxs font-medium">
            {formattedTime}
          </span>
        </div>

        {/* Horizontal lines across day columns */}
        {scrollStyle ? (
          <div className="min-w-0 flex-1 overflow-clip">
            <div style={scrollStyle}>{linesContent}</div>
          </div>
        ) : (
          linesContent
        )}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  isPrimaryPress,
  suppressNextClick,
  usePointerGesture,
} from "@/hooks/use-pointer-gesture";
import type {
  AllDayResizeState,
  CalendarEvent,
  PointerGestureStart,
} from "@/components/week-view-types";

interface UseAllDayResizeOptions {
  days: Date[];
  dayColumnWidth: number;
  allDayContainerRef: React.RefObject<HTMLDivElement | null>;
  events: CalendarEvent[];
  onEventChange?: (event: CalendarEvent) => void;
  onEventClick?: (event: CalendarEvent) => void;
}

interface UseAllDayResizeReturn {
  allDayResizeState: AllDayResizeState | null;
  handleAllDayResizePointerDown: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
    edge: "left" | "right" | "move",
    startColumn: number,
    endColumn: number,
  ) => void;
}

const DRAG_THRESHOLD_PX = 4;

function clamp(value: number, min: number, max: number): number {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

interface ResizeInfo {
  eventId: string;
  event: CalendarEvent;
  /** Pointer driving the gesture; moves from other pointers are ignored */
  pointerId: number;
  /** "mouse", "pen" or "touch" */
  pointerType: string;
  edge: "left" | "right" | "move";
  startClientX: number;
  isResizing: boolean;
  originalStartColumn: number;
  originalEndColumn: number;
  /** Column index where the gesture started (used for move delta) */
  startColumnIndex: number;
  /** Offset from cursor to event left edge when the gesture started (px) */
  cursorOffsetX: number;
  /** Offset from cursor to event top edge when the gesture started (px) */
  cursorOffsetY: number;
  /** Latest start column, committed to the parent on pointerup */
  currentStartColumn: number;
  /** Latest end column, committed to the parent on pointerup */
  currentEndColumn: number;
}

export function useAllDayResize({
  days,
  dayColumnWidth,
  allDayContainerRef,
  events,
  onEventChange,
  onEventClick,
}: UseAllDayResizeOptions): UseAllDayResizeReturn {
  const [allDayResizeState, setAllDayResizeState] =
    useState<AllDayResizeState | null>(null);
  const { startGesture } = usePointerGesture({
    containerRef: allDayContainerRef,
  });

  const resizeRef = useRef<ResizeInfo | null>(null);
  const onEventChangeRef = useRef(onEventChange);
  const onEventClickRef = useRef(onEventClick);
  const eventsRef = useRef(events);
  const daysRef = useRef(days);
  const dayColumnWidthRef = useRef(dayColumnWidth);

  useEffect(() => {
    onEventChangeRef.current = onEventChange;
  }, [onEventChange]);
  useEffect(() => {
    onEventClickRef.current = onEventClick;
  }, [onEventClick]);
  useEffect(() => {
    eventsRef.current = events;
  }, [events]);
  useEffect(() => {
    daysRef.current = days;
  }, [days]);
  useEffect(() => {
    dayColumnWidthRef.current = dayColumnWidth;
  }, [dayColumnWidth]);

  const handlePointerMoveRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerUpRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerCancelRef = useRef<((e: PointerEvent) => void) | null>(
    null,
  );

  const cleanup = useCallback(() => {
    if (handlePointerMoveRef.current) {
      window.removeEventListener("pointermove", handlePointerMoveRef.current);
    }
    if (handlePointerUpRef.current) {
      window.removeEventListener("pointerup", handlePointerUpRef.current);
    }
    if (handlePointerCancelRef.current) {
      window.removeEventListener(
        "pointercancel",
        handlePointerCancelRef.current,
      );
    }
    document.body.style.removeProperty("--cursor");
  }, []);

  useEffect(() => {
    handlePointerMoveRef.current = (e: PointerEvent) => {
      const resize = resizeRef.current;
      if (!resize || e.pointerId !== resize.pointerId) return;

      const deltaX = Math.abs(e.clientX - resize.startClientX);
      if (!resize.isResizing && deltaX < DRAG_THRESHOLD_PX) return;

      if (!resize.isResizing) {
        resize.isResizing = true;
        document.body.style.setProperty(
          "--cursor",
          resize.edge === "move" ? "grabbing" : "col-resize",
        );
      }

      const container = allDayContainerRef.current;
      if (!container) return;

      const rect = container.getBoundingClientRect();
      const colWidth = dayColumnWidthRef.current;
      const currentDays = daysRef.current;
      const columnIndex = clamp(
        Math.floor((e.clientX - rect.left) / colWidth),
        0,
        currentDays.length - 1,
      );

      let newStartColumn = resize.originalStartColumn;
      let newEndColumn = resize.originalEndColumn;

      if (resize.edge === "move") {
        const span = resize.originalEndColumn - resize.originalStartColumn;
        const delta = columnIndex - resize.startColumnIndex;
        newStartColumn = clamp(
          resize.originalStartColumn + delta,
          0,
          currentDays.length - 1 - span,
        );
        newEndColumn = newStartColumn + span;
      } else if (resize.edge === "right") {
        newEndColumn = Math.max(columnIndex, resize.originalStartColumn);
      } else {
        newStartColumn = Math.min(columnIndex, resize.originalEndColumn);
      }

      resize.currentStartColumn = newStartColumn;
      resize.currentEndColumn = newEndColumn;

      setAllDayResizeState({
        eventId: resize.eventId,
        event: resize.event,
        originalStartColumn: resize.originalStartColumn,
        originalEndColumn: resize.originalEndColumn,
        currentStartColumn: newStartColumn,
        currentEndColumn: newEndColumn,
        edge: resize.edge,
        isResizing: true,
        ...(resize.edge === "move"
          ? {
              clientX: e.clientX,
              clientY: e.clientY,
              cursorOffsetX: resize.cursorOffsetX,
              cursorOffsetY: resize.cursorOffsetY,
            }
          : {}),
      });
    };

    handlePointerUpRef.current = (e: PointerEvent) => {
      const resize = resizeRef.current;
      if (!resize || e.pointerId !== resize.pointerId) return;

      cleanup();
      resizeRef.current = null;
      setAllDayResizeState(null);

      // Touch selects on release, after the gesture, rather than on press
      if (resize.pointerType === "touch") {
        onEventClickRef.current?.(resize.event);
      }
      if (!resize.isResizing) return;
      // A move swaps the pressed bar for a ghost, so the browser's click
      // lands on the row and would clear the selection
      suppressNextClick(resize.pointerType);

      // Commit from the handler, never from inside a state updater:
      // updaters run during render, and calling the parent's setState
      // there triggers "Cannot update a component while rendering".
      const event = eventsRef.current.find((e) => e.id === resize.eventId);
      if (!event) return;

      const currentDays = daysRef.current;
      const newStartDate = currentDays[resize.currentStartColumn];
      const newEndDate = currentDays[resize.currentEndColumn];

      if (!newStartDate || !newEndDate) return;

      // Preserve time-of-day from original event
      const newStart = new Date(newStartDate);
      newStart.setHours(
        event.start.getHours(),
        event.start.getMinutes(),
        event.start.getSeconds(),
        event.start.getMilliseconds(),
      );

      const newEnd = new Date(newEndDate);
      newEnd.setHours(
        event.end.getHours(),
        event.end.getMinutes(),
        event.end.getSeconds(),
        event.end.getMilliseconds(),
      );

      // Move preserves the original isAllDay flag (duration unchanged).
      // Resize determines isAllDay by whether the span exceeds 24h.
      const isMove = resize.edge === "move";
      const MS_IN_24H = 24 * 60 * 60 * 1000;
      const isLongerThan24h = newEnd.getTime() - newStart.getTime() > MS_IN_24H;
      const isAllDay = isMove ? event.isAllDay === true : isLongerThan24h;

      onEventChangeRef.current?.({
        ...event,
        start: newStart,
        end: newEnd,
        isAllDay,
      });
    };

    // The browser took the pointer over (e.g. for a system gesture): drop
    // the gesture without committing it
    handlePointerCancelRef.current = (e: PointerEvent) => {
      const resize = resizeRef.current;
      if (!resize || e.pointerId !== resize.pointerId) return;

      cleanup();
      resizeRef.current = null;
      setAllDayResizeState(null);
    };
  }, [allDayContainerRef, cleanup]);

  const beginResize = useCallback(
    (
      { clientX, pointerId, pointerType }: PointerGestureStart,
      event: CalendarEvent,
      edge: "left" | "right" | "move",
      startColumn: number,
      endColumn: number,
    ) => {
      // Mouse and pen select the event immediately
      if (pointerType !== "touch") onEventClickRef.current?.(event);

      // Compute the column under the cursor at the start for move delta
      const container = allDayContainerRef.current;
      let startColumnIndex = startColumn;
      let cursorOffsetX = 0;
      const cursorOffsetY = 0;
      if (container) {
        const rect = container.getBoundingClientRect();
        const colWidth = dayColumnWidthRef.current;
        startColumnIndex = clamp(
          Math.floor((clientX - rect.left) / colWidth),
          0,
          daysRef.current.length - 1,
        );
        // Compute offset from cursor to the event element's top-left
        const eventLeft = rect.left + startColumn * colWidth;
        cursorOffsetX = clientX - eventLeft;
      }

      resizeRef.current = {
        eventId: event.id,
        event,
        pointerId,
        pointerType,
        edge,
        startClientX: clientX,
        isResizing: false,
        originalStartColumn: startColumn,
        originalEndColumn: endColumn,
        startColumnIndex,
        cursorOffsetX,
        cursorOffsetY,
        currentStartColumn: startColumn,
        currentEndColumn: endColumn,
      };

      setAllDayResizeState({
        eventId: event.id,
        event,
        originalStartColumn: startColumn,
        originalEndColumn: endColumn,
        currentStartColumn: startColumn,
        currentEndColumn: endColumn,
        edge,
        isResizing: false,
      });

      if (handlePointerMoveRef.current) {
        window.addEventListener("pointermove", handlePointerMoveRef.current);
      }
      if (handlePointerUpRef.current) {
        window.addEventListener("pointerup", handlePointerUpRef.current);
      }
      if (handlePointerCancelRef.current) {
        window.addEventListener(
          "pointercancel",
          handlePointerCancelRef.current,
        );
      }
    },
    [allDayContainerRef],
  );

  const handleAllDayResizePointerDown = useCallback(
    (
      e: React.PointerEvent<HTMLElement>,
      event: CalendarEvent,
      edge: "left" | "right" | "move",
      startColumn: number,
      endColumn: number,
    ) => {
      if (!isPrimaryPress(e)) return;
      e.stopPropagation();
      startGesture(e, (start) =>
        beginResize(start, event, edge, startColumn, endColumn),
      );
    },
    [startGesture, beginResize],
  );

  useEffect(() => {
    return cleanup;
  }, [cleanup]);

  return { allDayResizeState, handleAllDayResizePointerDown };
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  usePointerGesture,
  suppressNextClick,
} from "@/hooks/use-pointer-gesture";
import { snapToGrid } from "@/lib/event-utils";
import type {
  CalendarEvent,
  EventDragState,
  PointerGestureStart,
} from "@/components/week-view-types";

interface UseEventDragOptions {
  hourHeight: number;
  scrollContainerRef: React.RefObject<HTMLDivElement | null>;
  events: CalendarEvent[];
  days: Date[];
  dayColumnWidth: number;
  timeAxisWidth: number;
  /** Minute step the dragged start snaps to */
  snapMinutes: number;
  /** First visible hour: the top of the grid, and the earliest start */
  dayStartHour: number;
  /** Hour the grid ends at: the latest end */
  dayEndHour: number;
  /** Days `onDragNavigate` moves when the cursor is held at a side edge */
  edgeNavigationDays: number;
  onEventChange?: (event: CalendarEvent) => void;
  onEventClick?: (event: CalendarEvent) => void;
  onDragNavigate?: (daysDelta: number) => void;
}

interface UseEventDragReturn {
  dragState: EventDragState | null;
  handleEventPointerDown: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
  ) => void;
}

const DRAG_THRESHOLD_PX = 4;
const EDGE_ZONE_PX = 40;
const EDGE_NAV_DELAY_MS = 500;
const EDGE_NAV_REPEAT_MS = 800;
const AUTO_SCROLL_ZONE_PX = 60;
const AUTO_SCROLL_MAX_SPEED = 12;

function addMinutesToDate(date: Date, minutes: number): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  result.setMinutes(minutes);
  return result;
}

function clamp(value: number, min: number, max: number): number {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

interface DragInfo {
  eventId: string;
  event: CalendarEvent;
  /** Pointer driving the drag; moves from other pointers are ignored */
  pointerId: number;
  /** "mouse", "pen" or "touch" */
  pointerType: string;
  startClientY: number;
  startClientX: number;
  offsetWithinEvent: number;
  offsetWithinEventX: number;
  isDragging: boolean;
  durationMinutes: number;
  /** Latest snapped start, committed to the parent on pointerup */
  currentStart: Date;
  /** Latest snapped end, committed to the parent on pointerup */
  currentEnd: Date;
}

export function useEventDrag({
  hourHeight,
  scrollContainerRef,
  events,
  days,
  dayColumnWidth,
  timeAxisWidth,
  snapMinutes,
  dayStartHour,
  dayEndHour,
  edgeNavigationDays,
  onEventChange,
  onEventClick,
  onDragNavigate,
}: UseEventDragOptions): UseEventDragReturn {
  const [dragState, setDragState] = useState<EventDragState | null>(null);
  const { startGesture } = usePointerGesture({
    containerRef: scrollContainerRef,
  });

  const dragRef = useRef<DragInfo | null>(null);
  const onEventChangeRef = useRef(onEventChange);
  const onEventClickRef = useRef(onEventClick);
  const onDragNavigateRef = useRef(onDragNavigate);
  const eventsRef = useRef(events);
  const hourHeightRef = useRef(hourHeight);
  const daysRef = useRef(days);
  const dayColumnWidthRef = useRef(dayColumnWidth);
  const timeAxisWidthRef = useRef(timeAxisWidth);
  const snapMinutesRef = useRef(snapMinutes);
  const dayStartHourRef = useRef(dayStartHour);
  const dayEndHourRef = useRef(dayEndHour);
  const edgeNavigationDaysRef = useRef(edgeNavigationDays);

  useEffect(() => {
    onEventChangeRef.current = onEventChange;
  }, [onEventChange]);
  useEffect(() => {
    onEventClickRef.current = onEventClick;
  }, [onEventClick]);
  useEffect(() => {
    onDragNavigateRef.current = onDragNavigate;
  }, [onDragNavigate]);
  useEffect(() => {
    eventsRef.current = events;
  }, [events]);
  useEffect(() => {
    hourHeightRef.current = hourHeight;
  }, [hourHeight]);
  useEffect(() => {
    daysRef.current = days;
  }, [days]);
  useEffect(() => {
    dayColumnWidthRef.current = dayColumnWidth;
  }, [dayColumnWidth]);
  useEffect(() => {
    timeAxisWidthRef.current = timeAxisWidth;
  }, [timeAxisWidth]);
  useEffect(() => {
    snapMinutesRef.current = snapMinutes;
  }, [snapMinutes]);
  useEffect(() => {
    dayStartHourRef.current = dayStartHour;
  }, [dayStartHour]);
  useEffect(() => {
    dayEndHourRef.current = dayEndHour;
  }, [dayEndHour]);
  useEffect(() => {
    edgeNavigationDaysRef.current = edgeNavigationDays;
  }, [edgeNavigationDays]);

  // Edge navigation timer refs
  const edgeNavTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const edgeNavDirectionRef = useRef<number | null>(null);

  // Auto-scroll RAF ref
  const autoScrollRAFRef = useRef<number | null>(null);
  const autoScrollSpeedRef = useRef(0);

  // Store handlers in refs to break the circular dependency
  const handlePointerMoveRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerUpRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerCancelRef = useRef<((e: PointerEvent) => void) | null>(
    null,
  );

  const cancelEdgeNav = useCallback(() => {
    if (edgeNavTimerRef.current !== null) {
      clearTimeout(edgeNavTimerRef.current);
      edgeNavTimerRef.current = null;
    }
    edgeNavDirectionRef.current = null;
  }, []);

  const cancelAutoScroll = useCallback(() => {
    if (autoScrollRAFRef.current !== null) {
      cancelAnimationFrame(autoScrollRAFRef.current);
      autoScrollRAFRef.current = null;
    }
    autoScrollSpeedRef.current = 0;
  }, []);

  const cleanup = useCallback(() => {
    if (handlePointerMoveRef.current) {
      window.removeEventListener("pointermove", handlePointerMoveRef.current);
    }
    if (handlePointerUpRef.current) {
      window.removeEventListener("pointerup", handlePointerUpRef.current);
    }
    if (handlePointerCancelRef.current) {
      window.removeEventListener(
        "pointercancel",
        handlePointerCancelRef.current,
      );
    }
    cancelEdgeNav();
    cancelAutoScroll();
  }, [cancelEdgeNav, cancelAutoScroll]);

  // Auto-scroll loop
  const startAutoScrollLoop = useCallback(() => {
    if (autoScrollRAFRef.current !== null) return;

    const tick = () => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const speed = autoScrollSpeedRef.current;
      if (speed === 0) {
        autoScrollRAFRef.current = null;
        return;
      }

      container.scrollTop += speed;
      autoScrollRAFRef.current = requestAnimationFrame(tick);
    };

    autoScrollRAFRef.current = requestAnimationFrame(tick);
  }, [scrollContainerRef]);

  const scheduleEdgeNav = useCallback(
    (direction: number) => {
      if (edgeNavDirectionRef.current === direction) return;

      cancelEdgeNav();
      edgeNavDirectionRef.current = direction;

      const fireNav = () => {
        onDragNavigateRef.current?.(direction);
        edgeNavTimerRef.current = setTimeout(fireNav, EDGE_NAV_REPEAT_MS);
      };

      edgeNavTimerRef.current = setTimeout(fireNav, EDGE_NAV_DELAY_MS);
    },
    [cancelEdgeNav],
  );

  // Initialize the handlers once (stable references via refs)
  useEffect(() => {
    handlePointerMoveRef.current = (e: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag || e.pointerId !== drag.pointerId) return;

      const deltaY = Math.abs(e.clientY - drag.startClientY);
      const deltaX = Math.abs(e.clientX - drag.startClientX);
      if (
        !drag.isDragging &&
        deltaY < DRAG_THRESHOLD_PX &&
        deltaX < DRAG_THRESHOLD_PX
      )
        return;

      if (!drag.isDragging) {
        drag.isDragging = true;
      }

      const container = scrollContainerRef.current;
      if (!container) return;

      const containerRect = container.getBoundingClientRect();
      const scrollTop = container.scrollTop;
      const absoluteY =
        e.clientY - containerRect.top + scrollTop - drag.offsetWithinEvent;
      const absoluteX =
        e.clientX - containerRect.left - drag.offsetWithinEventX;
      // The grid's top edge is `dayStartHour`, not midnight
      const visibleStartMinutes = dayStartHourRef.current * 60;
      const visibleEndMinutes = dayEndHourRef.current * 60;
      const rawMinutes =
        visibleStartMinutes + (absoluteY / hourHeightRef.current) * 60;
      const snappedStartMinutes = snapToGrid(
        rawMinutes,
        snapMinutesRef.current,
      );
      const clampedStart = Math.max(
        visibleStartMinutes,
        Math.min(snappedStartMinutes, visibleEndMinutes - drag.durationMinutes),
      );

      // Column detection — based on raw cursor position over the grid
      const colWidth = dayColumnWidthRef.current;
      const visibleDays = daysRef.current;
      const gridLeftEdge = containerRect.left + timeAxisWidthRef.current;
      const cursorInGrid = e.clientX - gridLeftEdge;
      const columnIndex = clamp(
        Math.floor(cursorInGrid / colWidth),
        0,
        visibleDays.length - 1,
      );
      const targetDay = visibleDays[columnIndex];

      const currentStart = addMinutesToDate(targetDay, clampedStart);
      const currentEnd = addMinutesToDate(
        targetDay,
        clampedStart + drag.durationMinutes,
      );

      drag.currentStart = currentStart;
      drag.currentEnd = currentEnd;

      setDragState({
        eventId: drag.eventId,
        event: drag.event,
        originalStart: drag.event.start,
        originalEnd: drag.event.end,
        currentStart,
        currentEnd,
        currentDate: targetDay,
        isDragging: true,
        cursorY: absoluteY,
        cursorX: absoluteX,
        clientX: e.clientX - drag.offsetWithinEventX,
        clientY: e.clientY - drag.offsetWithinEvent,
      });

      // Edge-of-view week navigation
      // Trigger when cursor is within EDGE_ZONE_PX of the grid boundary OR past it
      const cursorXInGrid = e.clientX - gridLeftEdge;
      const gridWidth = colWidth * visibleDays.length;

      if (cursorXInGrid < EDGE_ZONE_PX) {
        scheduleEdgeNav(-edgeNavigationDaysRef.current);
      } else if (cursorXInGrid > gridWidth - EDGE_ZONE_PX) {
        scheduleEdgeNav(edgeNavigationDaysRef.current);
      } else {
        cancelEdgeNav();
      }

      // Auto-scroll at top/bottom edges
      const cursorYInContainer = e.clientY - containerRect.top;
      const containerHeight = containerRect.height;

      if (cursorYInContainer < AUTO_SCROLL_ZONE_PX) {
        const dist = cursorYInContainer;
        autoScrollSpeedRef.current =
          -AUTO_SCROLL_MAX_SPEED * (1 - dist / AUTO_SCROLL_ZONE_PX);
        startAutoScrollLoop();
      } else if (cursorYInContainer > containerHeight - AUTO_SCROLL_ZONE_PX) {
        const dist = containerHeight - cursorYInContainer;
        autoScrollSpeedRef.current =
          AUTO_SCROLL_MAX_SPEED * (1 - dist / AUTO_SCROLL_ZONE_PX);
        startAutoScrollLoop();
      } else {
        cancelAutoScroll();
      }
    };

    handlePointerUpRef.current = (e: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag || e.pointerId !== drag.pointerId) return;

      cleanup();
      dragRef.current = null;
      setDragState(null);

      // Touch selects on release, after the drag, rather than on press
      if (drag.pointerType === "touch") onEventClickRef.current?.(drag.event);
      if (!drag.isDragging) return;
      suppressNextClick(drag.pointerType);

      // Commit from the handler, never from inside a state updater:
      // updaters run during render, and calling the parent's setState
      // there triggers "Cannot update a component while rendering".
      const event = eventsRef.current.find((e) => e.id === drag.eventId);
      if (!event) return;

      onEventChangeRef.current?.({
        ...event,
        start: drag.currentStart,
        end: drag.currentEnd,
      });
    };

    // The browser took the pointer over (e.g. for a system gesture): drop
    // the drag without committing it
    handlePointerCancelRef.current = (e: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag || e.pointerId !== drag.pointerId) return;

      cleanup();
      dragRef.current = null;
      setDragState(null);
    };
  }, [
    scrollContainerRef,
    cleanup,
    scheduleEdgeNav,
    cancelEdgeNav,
    cancelAutoScroll,
    startAutoScrollLoop,
  ]);

  const beginDrag = useCallback(
    (
      {
        clientX,
        clientY,
        pointerId,
        pointerType,
        element,
      }: PointerGestureStart,
      event: CalendarEvent,
    ) => {
      // Mouse and pen select the event immediately
      if (pointerType !== "touch") onEventClickRef.current?.(event);

      const container = scrollContainerRef.current;
      if (!container) return;

      // Compute offset within the event element
      const targetRect = element.getBoundingClientRect();
      const offsetWithinEvent = clientY - targetRect.top;
      const offsetWithinEventX = clientX - targetRect.left;

      const startMinutes =
        event.start.getHours() * 60 + event.start.getMinutes();
      const endMinutes = event.end.getHours() * 60 + event.end.getMinutes();
      const durationMinutes = endMinutes - startMinutes;

      dragRef.current = {
        eventId: event.id,
        event,
        pointerId,
        pointerType,
        startClientY: clientY,
        startClientX: clientX,
        offsetWithinEvent,
        offsetWithinEventX,
        isDragging: false,
        durationMinutes,
        currentStart: event.start,
        currentEnd: event.end,
      };

      setDragState({
        eventId: event.id,
        event,
        originalStart: event.start,
        originalEnd: event.end,
        currentStart: event.start,
        currentEnd: event.end,
        currentDate: event.start,
        isDragging: false,
        cursorY: 0,
        cursorX: 0,
        clientX: 0,
        clientY: 0,
      });

      if (handlePointerMoveRef.current) {
        window.addEventListener("pointermove", handlePointerMoveRef.current);
      }
      if (handlePointerUpRef.current) {
        window.addEventListener("pointerup", handlePointerUpRef.current);
      }
      if (handlePointerCancelRef.current) {
        window.addEventListener(
          "pointercancel",
          handlePointerCancelRef.current,
        );
      }
    },
    [scrollContainerRef],
  );

  const handleEventPointerDown = useCallback(
    (e: React.PointerEvent<HTMLElement>, event: CalendarEvent) => {
      startGesture(e, (start) => beginDrag(start, event));
    },
    [startGesture, beginDrag],
  );

  // Cleanup on unmount
  useEffect(() => {
    return cleanup;
  }, [cleanup]);

  return { dragState, handleEventPointerDown };
}

"use client";

import { isSameDay, startOfDay } from "date-fns";
import { useCallback, useEffect, useRef, useState } from "react";
import {
  isPrimaryPress,
  suppressNextClick,
  usePointerGesture,
} from "@/hooks/use-pointer-gesture";
import { snapToGrid } from "@/lib/event-utils";
import type {
  CalendarEvent,
  EventResizeState,
  PointerGestureStart,
} from "@/components/week-view-types";

interface UseEventResizeOptions {
  hourHeight: number;
  scrollContainerRef: React.RefObject<HTMLDivElement | null>;
  events: CalendarEvent[];
  days: Date[];
  dayColumnWidth: number;
  timeAxisWidth: number;
  /** Minute step the dragged edge snaps to, and the shortest duration */
  snapMinutes: number;
  /** First visible hour: the top of the grid, and the earliest start */
  dayStartHour: number;
  /** Hour the grid ends at: the latest end */
  dayEndHour: number;
  /** Days `onResizeNavigate` moves when the cursor is held at a side edge */
  edgeNavigationDays: number;
  onEventChange?: (event: CalendarEvent) => void;
  onEventClick?: (event: CalendarEvent) => void;
  onResizeNavigate?: (daysDelta: number) => void;
}

interface UseEventResizeReturn {
  resizeState: EventResizeState | null;
  handleResizePointerDown: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
    edge: "top" | "bottom",
  ) => void;
}

const DRAG_THRESHOLD_PX = 4;
const AUTO_SCROLL_ZONE_PX = 60;
const AUTO_SCROLL_MAX_SPEED = 12;
const EDGE_ZONE_PX = 40;
const EDGE_NAV_DELAY_MS = 500;
const EDGE_NAV_REPEAT_MS = 800;

function addMinutesToDate(date: Date, minutes: number): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  result.setMinutes(minutes);
  return result;
}

function clamp(value: number, min: number, max: number): number {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

interface ResizeInfo {
  eventId: string;
  event: CalendarEvent;
  /** Pointer driving the resize; moves from other pointers are ignored */
  pointerId: number;
  /** "mouse", "pen" or "touch" */
  pointerType: string;
  edge: "top" | "bottom";
  startClientY: number;
  isResizing: boolean;
  originalStartMinutes: number;
  originalEndMinutes: number;
  originalStartDate: Date;
  originalEndDate: Date;
  /** Latest snapped start, committed to the parent on pointerup */
  currentStart: Date;
  /** Latest snapped end, committed to the parent on pointerup */
  currentEnd: Date;
}

export function useEventResize({
  hourHeight,
  scrollContainerRef,
  events,
  days,
  dayColumnWidth,
  timeAxisWidth,
  snapMinutes,
  dayStartHour,
  dayEndHour,
  edgeNavigationDays,
  onEventChange,
  onEventClick,
  onResizeNavigate,
}: UseEventResizeOptions): UseEventResizeReturn {
