    onEventChangeRef.current = onEventChange;
  }, [onEventChange]);
  useEffect(() => {
    onEventClickRef.current = onEventClick;
  }, [onEventClick]);
  useEffect(() => {
    onResizeNavigateRef.current = onResizeNavigate;
  }, [onResizeNavigate]);
  useEffect(() => {
    eventsRef.current = events;
